import os
from typing import Dict, Any, Optional
import boto3
from botocore.exceptions import ClientError

def extract_expense_fields(image_path: str) -> Dict[str, Any]:
    """
    Extract structured expense fields from an image using Amazon Textract AnalyzeExpense.

    Args:
        image_path: Path to the image file (JPEG, PNG, PDF, etc.)

    Returns:
        Dictionary with normalized expense fields according to standard schema.
    """
    # Provider-identifying client setup
    client = boto3.client('textract', region_name=os.getenv('AWS_REGION', 'us-east-1'))

    # Read image bytes
    with open(image_path, 'rb') as image_file:
        image_bytes = image_file.read()

    # Provider-specific API call
    try:
        response = client.analyze_expense(Document={'Bytes': image_bytes})
    except ClientError as e:
        raise RuntimeError(f"Textract API error: {e}")

    # Normalize extracted fields into standard schema
    normalized = {
        'vendor_name': None,
        'invoice_date': None,
        'invoice_number': None,
        'total_amount': None,
        'tax_amount': None,
        'currency': 'USD',
        'line_items': []
    }

    # Parse Textract response
    for expense_doc in response.get('ExpenseDocuments', []):
        # Extract summary fields
        for field in expense_doc.get('SummaryFields', []):
            label = field.get('Type', {}).get('Text', '').lower()
            value_text = field.get('ValueDetection', {}).get('Text')

            if 'vendor' in label and value_text:
                normalized['vendor_name'] = value_text
            elif 'date' in label and value_text:
                normalized['invoice_date'] = value_text
            elif 'invoice' in label and 'number' in label and value_text:
                normalized['invoice_number'] = value_text
            elif 'total' in label and value_text:
                normalized['total_amount'] = _parse_amount(value_text)
                # Try to extract currency from total field
                currency = field.get('ValueDetection', {}).get('Currency', {}).get('Code')
                if currency:
                    normalized['currency'] = currency
            elif 'tax' in label and value_text:
                normalized['tax_amount'] = _parse_amount(value_text)

        # Extract line items
        for group in expense_doc.get('LineItemGroups', []):
            for item in group.get('LineItems', []):
                line_item = {}
                for field in item.get('LineItemExpenseFields', []):
                    label = field.get('Type', {}).get('Text', '').lower()
                    value_text = field.get('ValueDetection', {}).get('Text')

                    if 'description' in label and value_text:
                        line_item['description'] = value_text
                    elif 'quantity' in label and value_text:
                        line_item['quantity'] = _parse_quantity(value_text)
                    elif 'unit' in label and 'price' in label and value_text:
                        line_item['unit_price'] = _parse_amount(value_text)
                    elif 'amount' in label and value_text:
                        line_item['amount'] = _parse_amount(value_text)

                if line_item:
                    normalized['line_items'].append(line_item)

    return normalized

def _parse_amount(amount_str: str) -> Optional[float]:
    """Parse amount string to float, removing currency symbols."""
    try:
        # Remove common currency symbols and thousands separators
        cleaned = ''.join(c for c in amount_str if c.isdigit() or c in '.-')
        return float(cleaned) if cleaned else None
    except (ValueError, AttributeError):
        return None

def _parse_quantity(quantity_str: str) -> Optional[float]:
    """Parse quantity string to float."""
    try:
        return float(quantity_str)
    except (ValueError, AttributeError):
        return None
